# AC-01: check_agentcore_vpc_configuration
# ===================================================================
class TestAC01VPCConfiguration:
    """AC-01: Check VPC configuration for AgentCore resources."""

    @patch("agentcore_app.agentcore_client", None)
    def test_ac01_client_unavailable_returns_na(self):
        result = agentcore_app.check_agentcore_vpc_configuration()
        findings = extract_csv_data(result)
        assert len(findings) >= 1
        assert findings[0]["Status"] == "N/A"
        assert findings[0]["Check_ID"] == "AC-01"

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_ac01_no_runtimes_returns_na(self, mock_ac, mock_ec2):
        mock_ac.list_agent_runtimes.return_value = {"agentRuntimes": []}
        result = agentcore_app.check_agentcore_vpc_configuration()
        findings = extract_csv_data(result)
        assert len(findings) >= 1
        assert findings[0]["Status"] == "N/A"

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_ac01_runtime_public_returns_failed(self, mock_ac, mock_ec2):
        mock_ac.list_agent_runtimes.return_value = {
            "agentRuntimes": [{"agentRuntimeId": "rt-1", "agentRuntimeName": "TestRT"}]
        }
        mock_ac.get_agent_runtime.return_value = {
            "networkConfiguration": {"networkMode": "PUBLIC"}
        }
        result = agentcore_app.check_agentcore_vpc_configuration()
        findings = extract_csv_data(result)
        assert len(findings) >= 1
        assert findings[0]["Status"] == "Failed"
        assert findings[0]["Severity"] == "High"

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_ac01_runtime_vpc_configured_returns_passed(self, mock_ac, mock_ec2):
        mock_ac.list_agent_runtimes.return_value = {
            "agentRuntimes": [{"agentRuntimeId": "rt-1", "agentRuntimeName": "TestRT"}]
        }
        mock_ac.get_agent_runtime.return_value = {
            "networkConfiguration": {
                "networkMode": "VPC",
                "networkModeConfig": {
                    "subnets": ["subnet-123"],
                    "requireServiceS3Endpoint": False,
                },
            }
        }
        mock_ec2.describe_subnets.return_value = {
            "Subnets": [{"SubnetId": "subnet-123"}]
        }
        mock_ec2.describe_route_tables.return_value = {
            "RouteTables": [{"Routes": [{"GatewayId": "local"}]}]
        }
        result = agentcore_app.check_agentcore_vpc_configuration()
        findings = extract_csv_data(result)
        assert len(findings) >= 1
        assert findings[0]["Status"] == "Passed"

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_ac01_runtime_public_subnet_returns_failed(self, mock_ac, mock_ec2):
        """A VPC-mode runtime whose subnet routes to an internet gateway fails.

        The route-table leg reads networkModeConfig.subnets. It spent its whole
        life reading Bedrock's subnetIds spelling instead, which GetAgentRuntime
        never returns, so this is the case that distinguishes the two: with the
        wrong key the subnet list is empty and the runtime passes.
        """
        mock_ac.list_agent_runtimes.return_value = {
            "agentRuntimes": [{"agentRuntimeId": "rt-1", "agentRuntimeName": "TestRT"}]
        }
        mock_ac.get_agent_runtime.return_value = {
            "networkConfiguration": {
                "networkMode": "VPC",
                "networkModeConfig": {"subnets": ["subnet-public"]},
            }
        }
        mock_ec2.describe_subnets.return_value = {
            "Subnets": [{"SubnetId": "subnet-public"}]
        }
        mock_ec2.describe_route_tables.return_value = {
            "RouteTables": [{"Routes": [{"GatewayId": "igw-0abc"}]}]
        }
        result = agentcore_app.check_agentcore_vpc_configuration()
        findings = extract_csv_data(result)
        public = [
            f for f in findings if f["Finding"] == "AgentCore Runtime Public Subnet"
        ]
        assert len(public) == 1
        assert public[0]["Status"] == "Failed"
        assert public[0]["Severity"] == "Medium"
        assert "subnet-public" in public[0]["Finding_Details"]
        mock_ec2.describe_subnets.assert_called_once_with(SubnetIds=["subnet-public"])

    def _vpc_runtime(self, mock_ac, mock_ec2):
        mock_ac.list_agent_runtimes.return_value = {
            "agentRuntimes": [{"agentRuntimeId": "rt-1", "agentRuntimeName": "TestRT"}]
        }
        mock_ac.get_agent_runtime.return_value = {
            "networkConfiguration": {
                "networkMode": "VPC",
                "networkModeConfig": {
                    "subnets": ["subnet-main"],
                    "requireServiceS3Endpoint": False,
                },
            }
        }
        mock_ec2.describe_subnets.return_value = {
            "Subnets": [{"SubnetId": "subnet-main", "VpcId": "vpc-1"}]
        }

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_ac01_unassociated_subnet_reads_the_main_route_table(
        self, mock_ac, mock_ec2
    ):
        """A subnet with no explicit association routes through the main table.

        Without the fallback the association filter returns no table, no route
        is read, and a subnet the main table sends to an igw- passes.
        """
        self._vpc_runtime(mock_ac, mock_ec2)

        def route_tables(Filters):
            if Filters[0]["Name"] == "association.subnet-id":
                return {"RouteTables": []}
            assert {"Name": "association.main", "Values": ["true"]} in Filters
            assert {"Name": "vpc-id", "Values": ["vpc-1"]} in Filters
            return {"RouteTables": [{"Routes": [{"GatewayId": "igw-0main"}]}]}

        mock_ec2.describe_route_tables.side_effect = route_tables
        findings = extract_csv_data(agentcore_app.check_agentcore_vpc_configuration())
        public = [
            f for f in findings if f["Finding"] == "AgentCore Runtime Public Subnet"
        ]

        assert len(public) == 1
        assert "subnet-main" in public[0]["Finding_Details"]
        assert mock_ec2.describe_route_tables.call_count == 2

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_ac01_blackholed_igw_route_is_not_exposure(self, mock_ac, mock_ec2):
        self._vpc_runtime(mock_ac, mock_ec2)
        mock_ec2.describe_route_tables.return_value = {
            "RouteTables": [
                {"Routes": [{"GatewayId": "igw-0gone", "State": "blackhole"}]}
            ]
        }

        findings = extract_csv_data(agentcore_app.check_agentcore_vpc_configuration())

        # The egress leg reports separately; the subnet verdict is the one
        # named for the VPC configuration.
        verdicts = [
            f["Status"]
            for f in findings
            if f["Finding"] == "AgentCore VPC Configuration Check"
        ]
        assert verdicts == ["Passed"]
        assert not [
            f for f in findings if f["Finding"] == "AgentCore Runtime Public Subnet"
        ]

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_ac01_route_read_failure_is_na_not_a_pass(self, mock_ac, mock_ec2):
        self._vpc_runtime(mock_ac, mock_ec2)
        mock_ec2.describe_route_tables.side_effect = _make_client_error(
            "UnauthorizedOperation", "denied"
        )

        findings = extract_csv_data(agentcore_app.check_agentcore_vpc_configuration())
        subnet_verdicts = [
            f
            for f in findings
            if f["Finding"]
            in (
                "AgentCore Runtime VPC Configuration",
                "AgentCore VPC Configuration Check",
            )
        ]

        assert [f["Status"] for f in subnet_verdicts] == ["N/A"]
        assert "ec2:DescribeRouteTables" in subnet_verdicts[0]["Resolution"]

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_ac01_unreadable_runtime_is_na_not_a_pass(self, mock_ac, mock_ec2):
        """A GetAgentRuntime error other than not-found must not read as a pass.

        The error used to be logged only, so the runtime contributed no finding
        and the empty list became "All AgentCore resources have proper VPC
        configuration".
        """
        mock_ac.list_agent_runtimes.return_value = {
            "agentRuntimes": [{"agentRuntimeId": "rt-1", "agentRuntimeName": "TestRT"}]
        }
        mock_ac.get_agent_runtime.side_effect = _make_client_error(
            "AccessDeniedException", "denied"
        )

        findings = extract_csv_data(agentcore_app.check_agentcore_vpc_configuration())

        assert "Passed" not in [f["Status"] for f in findings]
        unread = [f for f in findings if "rt-1" in f["Finding_Details"]]
        assert [f["Status"] for f in unread] == ["N/A"]
        assert unread[0]["Severity"] == "Informational"
        assert "TestRT" in unread[0]["Finding_Details"]
        assert "AccessDeniedException" in unread[0]["Finding_Details"]
        assert "bedrock-agentcore:GetAgentRuntime" in unread[0]["Resolution"]
        assert_finding_schema(unread[0])

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_ac01_missing_subnet_is_reported_and_the_others_still_judged(
        self, mock_ac, mock_ec2
    ):
        """DescribeSubnets fails the whole call when one id does not exist.

        Without the per-subnet retry the public subnet beside the missing one is
        never judged, and the finding asks for ec2:DescribeSubnets, which the
        role already holds.
        """
        mock_ac.list_agent_runtimes.return_value = {
            "agentRuntimes": [{"agentRuntimeId": "rt-1", "agentRuntimeName": "TestRT"}]
        }
        mock_ac.get_agent_runtime.return_value = {
            "networkConfiguration": {
                "networkMode": "VPC",
                "networkModeConfig": {"subnets": ["subnet-public", "subnet-gone"]},
            }
        }

        def describe_subnets(SubnetIds):
            if "subnet-gone" in SubnetIds:
                raise _make_client_error("InvalidSubnetID.NotFound", "not found")
            return {"Subnets": [{"SubnetId": s, "VpcId": "vpc-1"} for s in SubnetIds]}

        mock_ec2.describe_subnets.side_effect = describe_subnets
        mock_ec2.describe_route_tables.return_value = {
            "RouteTables": [{"Routes": [{"GatewayId": "igw-0abc"}]}]
        }

        findings = extract_csv_data(agentcore_app.check_agentcore_vpc_configuration())

        public = [
            f for f in findings if f["Finding"] == "AgentCore Runtime Public Subnet"
        ]
        assert len(public) == 1
        assert "subnet-public" in public[0]["Finding_Details"]
        missing = [f for f in findings if "subnet-gone" in f["Finding_Details"]]
        assert [f["Status"] for f in missing] == ["N/A"]
        assert "not present" in missing[0]["Finding_Details"]
        assert "ec2:DescribeSubnets" not in missing[0]["Resolution"]
        assert "Passed" not in [
            f["Status"]
            for f in findings
            if f["Finding"] == "AgentCore VPC Configuration Check"
        ]

    @patch("agentcore_app.agentcore_client")
    def test_ac01_exception_returns_incomplete_na(self, mock_ac):
        mock_ac.list_agent_runtimes.side_effect = Exception("VPC error")
        result = agentcore_app.check_agentcore_vpc_configuration()
        findings = extract_csv_data(result)
        assert len(findings) >= 1
        assert findings[0]["Status"] == "N/A"
        assert findings[0]["Severity"] == "Informational"

    @patch("agentcore_app.agentcore_client", None)
    def test_ac01_schema_valid(self):
        result = agentcore_app.check_agentcore_vpc_configuration()
        for f in extract_csv_data(result):
            assert_finding_schema(f)


