# AC-02: check_agentcore_full_access_roles
# ===================================================================
class TestAC02FullAccessRoles:
    """AC-02: Check for roles with AgentCore full access."""

    @patch("agentcore_app.agentcore_client", None)
    def test_ac02_client_unavailable_returns_na(self, empty_permission_cache):
        result = agentcore_app.check_agentcore_full_access_roles(empty_permission_cache)
        findings = extract_csv_data(result)
        assert len(findings) >= 1
        assert findings[0]["Check_ID"] == "AC-02"

    @patch("agentcore_app.agentcore_client")
    def test_ac02_no_full_access_returns_passed(
        self, mock_ac, permission_cache_compliant
    ):
        result = agentcore_app.check_agentcore_full_access_roles(
            permission_cache_compliant
        )
        findings = extract_csv_data(result)
        assert len(findings) >= 1
        # Compliant cache has no AgentCore full access

    @patch("agentcore_app.agentcore_client")
    def test_ac02_full_access_returns_failed(
        self, mock_ac, permission_cache_agentcore_full_access
    ):
        result = agentcore_app.check_agentcore_full_access_roles(
            permission_cache_agentcore_full_access
        )
        findings = extract_csv_data(result)
        assert len(findings) >= 1
        has_failed = any(f["Status"] == "Failed" for f in findings)
        assert has_failed

    def test_ac02_detects_wildcard_in_generic_attached_policy_document(self):
        permission_cache = {
            "role_permissions": {
                "AgentCoreOperator": {
                    "attached_policies": [
                        {
                            "name": "AgentCoreOps",
                            "document": {
                                "Statement": {
                                    "Effect": "Allow",
                                    "Action": "bedrock-agentcore:*",
                                    "Resource": "*",
                                }
                            },
                        }
                    ],
                    "inline_policies": [],
                }
            }
        }

        findings = agentcore_app.check_agentcore_full_access_roles(permission_cache)

        wildcard_finding = next(
            finding
            for finding in findings
            if finding["Finding"] == "AgentCore IAM Wildcard Permissions"
        )
        assert wildcard_finding["Status"] == "Failed"
        assert "AgentCoreOperator" in wildcard_finding["Finding_Details"]

    @pytest.mark.parametrize(
        "action",
        [
            "bedrock-agentcore:*",
            "bedrock-agentcore:Get*",
            "bedrock-agentcore:*Runtime*",
            "BEDROCK-AGENTCORE:GetAgentRuntim?",
        ],
        ids=["full", "prefix", "embedded", "case-insensitive-question-mark"],
    )
    def test_ac02_detects_agent_platform_wildcard_action_patterns(self, action):
        permission_cache = {
            "role_permissions": {
                "WildcardRole": {
                    "attached_policies": [],
                    "inline_policies": [
                        {
                            "name": "WildcardPolicy",
                            "document": {
                                "Statement": {
                                    "Effect": "Allow",
                                    "Action": action,
                                    "Resource": "*",
                                }
                            },
                        }
                    ],
                }
            }
        }

        findings = agentcore_app.check_agentcore_full_access_roles(permission_cache)

        wildcard_finding = next(
            finding
            for finding in findings
            if finding["Finding"] == "AgentCore IAM Wildcard Permissions"
        )
        assert wildcard_finding["Status"] == "Failed"
        assert "WildcardRole" in wildcard_finding["Finding_Details"]

    @pytest.mark.parametrize(
        "not_action",
        [
            ["bedrock-agentcore:DeleteAgentRuntime"],
        ],
        ids=["partial-agentcore"],
    )
    def test_ac02_detects_allow_not_action_that_includes_platform_services(
        self, not_action
    ):
        permission_cache = {
            "role_permissions": {
                "AllowExceptRole": {
                    "attached_policies": [],
                    "inline_policies": [
                        {
                            "name": "AllowExceptPolicy",
                            "document": {
                                "Statement": {
                                    "Effect": "Allow",
                                    "NotAction": not_action,
                                    "Resource": "*",
                                }
                            },
                        }
                    ],
                }
            }
        }

        findings = agentcore_app.check_agentcore_full_access_roles(permission_cache)

        wildcard_finding = next(
            finding
            for finding in findings
            if finding["Finding"] == "AgentCore IAM Wildcard Permissions"
        )
        assert wildcard_finding["Status"] == "Failed"
        assert "AllowExceptRole" in wildcard_finding["Finding_Details"]
        assert "allow-except" in wildcard_finding["Finding_Details"]

    @pytest.mark.parametrize(
        "not_action",
        [
            ["iam:*", "organizations:*"],
            ["s3:DeleteBucket"],
        ],
        ids=["administrator-except-iam", "administrator-except-one-action"],
    )
    def test_ac02_reports_not_action_that_names_no_platform_namespace(self, not_action):
        """A NotAction naming no platform namespace still grants every AgentCore
        action, so AC-02 reports it as it reports ``Action: "*"``. This test
        asserted Passed before the whole-population change."""
        permission_cache = {
            "role_permissions": {
                "AllowExceptRole": {
                    "attached_policies": [],
                    "inline_policies": [
                        {
                            "name": "AllowExceptPolicy",
                            "document": {
                                "Statement": {
                                    "Effect": "Allow",
                                    "NotAction": not_action,
                                    "Resource": "*",
                                }
                            },
                        }
                    ],
                }
            }
        }

        findings = agentcore_app.check_agentcore_full_access_roles(permission_cache)

        wildcard_finding = next(
            finding
            for finding in findings
            if finding["Finding"] == "AgentCore IAM Wildcard Permissions"
        )
        assert wildcard_finding["Status"] == "Failed"
        assert "role AllowExceptRole" in wildcard_finding["Finding_Details"]
        assert "Passed" not in [finding["Status"] for finding in findings]

    @pytest.mark.parametrize(
        "not_action",
        [
            ["bedrock-agentcore:*", "bedrock-agentcore:*"],
            ["bedrock-*:*", "bedrock-agentcore:*"],
            "*",
            "*:*",
        ],
        ids=["both-namespaces", "service-pattern", "all-actions", "all-services"],
    )
    def test_ac02_ignores_not_action_that_excludes_all_platform_access(
        self, not_action
    ):
        permission_cache = {
            "role_permissions": {
                "ExcludedPlatformRole": {
                    "attached_policies": [],
                    "inline_policies": [
                        {
                            "name": "ExcludedPlatformPolicy",
                            "document": {
                                "Statement": {
                                    "Effect": "Allow",
                                    "NotAction": not_action,
                                    "Resource": "*",
                                }
                            },
                        }
                    ],
                }
            }
        }

        findings = agentcore_app.check_agentcore_full_access_roles(permission_cache)

        assert len(findings) == 1
        assert findings[0]["Status"] == "Passed"

    @pytest.mark.parametrize(
        ("action", "resource"),
        [
            ("bedrock-agentcore:GetAgentRuntime", "*"),
            ("unrelated-service:Get*", "*"),
            ("bedrock-agentcore-control:*", "*"),
            (
                "bedrock-agentcore:Get*",
                "arn:aws:bedrock-agentcore:us-east-1:123456789012:runtime/runtime-1",
            ),
        ],
        ids=[
            "exact-action",
            "unrelated-service",
            "invalid-iam-prefix",
            "scoped-resource",
        ],
    )
    def test_ac02_ignores_non_risky_or_unrelated_action_patterns(
        self, action, resource
    ):
        permission_cache = {
            "role_permissions": {
                "ScopedRole": {
                    "attached_policies": [],
                    "inline_policies": [
                        {
                            "name": "ScopedPolicy",
                            "document": {
                                "Statement": {
                                    "Effect": "Allow",
                                    "Action": action,
                                    "Resource": resource,
                                }
                            },
                        }
                    ],
                }
            }
        }

        findings = agentcore_app.check_agentcore_full_access_roles(permission_cache)

        assert len(findings) == 1
        assert findings[0]["Status"] == "Passed"

    @staticmethod
    def _administrator_cache(statements):
        return {
            "role_permissions": {
                "Administrator": {
                    "attached_policies": [
                        {
                            "name": "AdministratorAccess",
                            "document": {"Statement": statements},
                        }
                    ],
                    "inline_policies": [],
                }
            }
        }

    def test_ac02_reports_a_bare_wildcard_action(self):
        """``Action: "*"`` on every resource grants every AgentCore action. This
        case asserted Passed before the whole-population change."""
        findings = agentcore_app.check_agentcore_full_access_roles(
            self._administrator_cache(
                {"Effect": "Allow", "Action": "*", "Resource": "*"}
            )
        )

        wildcard_finding = next(
            finding
            for finding in findings
            if finding["Finding"] == "AgentCore IAM Wildcard Permissions"
        )
        assert wildcard_finding["Status"] == "Failed"
        assert "role Administrator (*)" in wildcard_finding["Finding_Details"]
        assert "Passed" not in [finding["Status"] for finding in findings]

    def test_ac02_a_platform_deny_removes_a_bare_wildcard(self):
        findings = agentcore_app.check_agentcore_full_access_roles(
            self._administrator_cache(
                [
                    {"Effect": "Allow", "Action": "*", "Resource": "*"},
                    {
                        "Effect": "Deny",
                        "Action": "bedrock-agentcore:*",
                        "Resource": "*",
                    },
                ]
            )
        )

        assert len(findings) == 1
        assert findings[0]["Status"] == "Passed"

    @pytest.mark.parametrize(
        "not_action",
        [
            ["iam:*", "organizations:*"],
            ["s3:DeleteBucket"],
        ],
        ids=["administrator-except-iam", "administrator-except-one-action"],
    )
    def test_ac02_reports_not_action_that_names_no_platform_namespace_as_merged(
        self, not_action
    ):
        """A NotAction naming no platform namespace is an administrator-style
        grant. The merged read-and-write leg (AIR-FND-IAM-09) reports it beside
        the wildcard row."""
        permission_cache = {
            "role_permissions": {
                "AllowExceptRole": {
                    "attached_policies": [],
                    "inline_policies": [
                        {
                            "name": "AllowExceptPolicy",
                            "document": {
                                "Statement": {
                                    "Effect": "Allow",
                                    "NotAction": not_action,
                                    "Resource": "*",
                                }
                            },
                        }
                    ],
                }
            }
        }

        findings = agentcore_app.check_agentcore_full_access_roles(permission_cache)

        merged = [
            finding
            for finding in findings
            if finding["Finding"] == "AgentCore Read and Write Merged in One Grant"
        ]
        assert len(merged) == 1
        assert merged[0]["Status"] == "Failed"
        assert merged[0]["Finding_Details"].startswith("Role 'AllowExceptRole': ")

