class TestAC22SinkScopeValues:
    """AC-22: a sink is scoped by the values it names, not by the keys present."""

    _SINK = TestAC22TelemetrySinkScope._SINK

    @staticmethod
    def _policy(*statements):
        return {"Policy": json.dumps({"Statement": list(statements)})}

    @staticmethod
    def _open(condition=None, **extra):
        statement = {
            "Effect": "Allow",
            "Principal": "*",
            "Action": "oam:CreateLink",
            "Resource": "*",
        }
        if condition is not None:
            statement["Condition"] = condition
        statement.update(extra)
        return statement

    @pytest.mark.parametrize(
        "principal",
        [
            {"AWS": "arn:aws:iam::*:root"},
            {"AWS": ["arn:aws:iam::111122223333:root", "arn:aws:iam::*:root"]},
            ["arn:aws:iam::111122223333:root", "*"],
        ],
    )
    @patch("agentcore_app.oam_client")
    def test_a_wildcard_in_any_principal_value_fails(self, mock_oam, principal):
        mock_oam.list_sinks.return_value = {"Items": [self._SINK]}
        statement = self._open()
        statement["Principal"] = principal
        mock_oam.get_sink_policy.return_value = self._policy(statement)

        findings = agentcore_app.check_agentcore_telemetry_sink_scope()

        assert findings[0]["Status"] == "Failed"

    @patch("agentcore_app.oam_client")
    def test_a_not_principal_allow_is_not_scoped_by_its_list(self, mock_oam):
        mock_oam.list_sinks.return_value = {"Items": [self._SINK]}
        statement = self._open()
        del statement["Principal"]
        statement["NotPrincipal"] = {"AWS": "arn:aws:iam::444455556666:root"}
        mock_oam.get_sink_policy.return_value = self._policy(statement)

        findings = agentcore_app.check_agentcore_telemetry_sink_scope()

        assert findings[0]["Status"] == "Failed"
        assert "NotPrincipal" in findings[0]["Finding_Details"]

    @pytest.mark.parametrize(
        "operator",
        [
            "StringNotEquals",
            "StringNotLike",
            "StringEqualsIfExists",
            "StringLikeIfExists",
            "ForAllValues:StringEquals",
            "ForAnyValue:StringNotEquals",
            "ArnLike",
            "Null",
        ],
    )
    @patch("agentcore_app.oam_client")
    def test_an_org_key_under_a_non_binding_operator_fails(self, mock_oam, operator):
        mock_oam.list_sinks.return_value = {"Items": [self._SINK]}
        mock_oam.get_sink_policy.return_value = self._policy(
            self._open({operator: {"aws:PrincipalOrgID": "o-a1b2c3d4e5"}})
        )

        findings = agentcore_app.check_agentcore_telemetry_sink_scope()

        assert findings[0]["Status"] == "Failed"

    @pytest.mark.parametrize(
        "key, value",
        [
            ("aws:PrincipalOrgID", "o-*"),
            ("aws:PrincipalOrgID", "*"),
            ("aws:PrincipalOrgID", "o-a1b2c3d4e?"),
            ("aws:PrincipalOrgID", ["o-a1b2c3d4e5", "o-*"]),
            ("aws:PrincipalOrgPaths", "o-*/r-ab12/*"),
            ("aws:PrincipalOrgPaths", "*"),
            ("aws:PrincipalOrgPaths", ["o-a1b2c3d4e5/*", "*/r-ab12/*"]),
            ("aws:PrincipalOrgID", []),
        ],
    )
    @patch("agentcore_app.oam_client")
    def test_a_wildcard_organization_value_fails(self, mock_oam, key, value):
        mock_oam.list_sinks.return_value = {"Items": [self._SINK]}
        mock_oam.get_sink_policy.return_value = self._policy(
            self._open({"StringLike": {key: value}})
        )

        findings = agentcore_app.check_agentcore_telemetry_sink_scope()

        assert findings[0]["Status"] == "Failed"

    @pytest.mark.parametrize(
        "operator, key, value",
        [
            ("StringEquals", "aws:PrincipalOrgID", "o-a1b2c3d4e5"),
            ("StringEqualsIgnoreCase", "aws:PrincipalOrgID", "o-a1b2c3d4e5"),
            ("ForAnyValue:StringLike", "aws:PrincipalOrgPaths", "o-a1b2c3d4e5/*"),
            (
                "ForAnyValue:StringLike",
                "aws:PrincipalOrgPaths",
                ["o-a1b2c3d4e5/r-ab12/ou-ab12-11111111/*", "o-a1b2c3d4e5/r-ab12/*"],
            ),
        ],
    )
    @patch("agentcore_app.oam_client")
    def test_a_named_organization_still_passes(self, mock_oam, operator, key, value):
        mock_oam.list_sinks.return_value = {"Items": [self._SINK]}
        mock_oam.get_sink_policy.return_value = self._policy(
            self._open({operator: {key: value}})
        )

        findings = agentcore_app.check_agentcore_telemetry_sink_scope()

        assert findings[0]["Status"] == "Passed"

    @patch("agentcore_app.oam_client")
    def test_a_binding_key_beside_a_non_binding_one_passes(self, mock_oam):
        mock_oam.list_sinks.return_value = {"Items": [self._SINK]}
        mock_oam.get_sink_policy.return_value = self._policy(
            self._open(
                {
                    "StringEqualsIfExists": {"aws:PrincipalOrgPaths": "o-*/*"},
                    "StringEquals": {"aws:PrincipalOrgID": "o-a1b2c3d4e5"},
                }
            )
        )

        findings = agentcore_app.check_agentcore_telemetry_sink_scope()

        assert findings[0]["Status"] == "Passed"

    @patch("agentcore_app.oam_client")
    def test_one_wildcard_sink_among_scoped_ones_fails_alone(self, mock_oam):
        second = dict(
            self._SINK,
            Arn="arn:aws:oam:us-east-1:123456789012:sink/s-2",
            Name="open-sink",
        )
        mock_oam.list_sinks.return_value = {"Items": [self._SINK, second]}
        policies = {
            self._SINK["Arn"]: self._policy(
                self._open({"StringEquals": {"aws:PrincipalOrgID": "o-a1b2c3d4e5"}})
            ),
            second["Arn"]: self._policy(
                self._open({"StringLike": {"aws:PrincipalOrgID": "o-*"}})
            ),
        }
        mock_oam.get_sink_policy.side_effect = lambda SinkIdentifier: policies[
            SinkIdentifier
        ]

        findings = agentcore_app.check_agentcore_telemetry_sink_scope()

        by_sink = {
            ("open-sink" if "open-sink" in f["Finding_Details"] else "central"): f[
                "Status"
            ]
            for f in findings
        }
        assert by_sink == {"central": "Passed", "open-sink": "Failed"}

    @patch("agentcore_app.oam_client")
    def test_a_negated_statement_beside_a_scoped_one_fails(self, mock_oam):
        mock_oam.list_sinks.return_value = {"Items": [self._SINK]}
        mock_oam.get_sink_policy.return_value = self._policy(
            self._open({"StringEquals": {"aws:PrincipalOrgID": "o-a1b2c3d4e5"}}),
            self._open(
                {"StringNotEquals": {"aws:PrincipalOrgID": "o-a1b2c3d4e5"}},
                Action="oam:UpdateLink",
            ),
        )

        findings = agentcore_app.check_agentcore_telemetry_sink_scope()

        assert findings[0]["Status"] == "Failed"
        assert "1 Allow statement" in findings[0]["Finding_Details"]

    @patch("agentcore_app.oam_client")
    def test_no_sink_names_the_unread_source_link_leg(self, mock_oam):
        mock_oam.list_sinks.return_value = {"Items": []}

        findings = agentcore_app.check_agentcore_telemetry_sink_scope()

        assert findings[0]["Status"] == "N/A"
        assert "oam:ListLinks" in findings[0]["Finding_Details"]
        mock_oam.list_links.assert_not_called()


# ===================================================================
# AC-23: check_agentcore_memory_record_access_scope
# ===================================================================
class TestAC23MemoryRecordAccessScope:
    """AC-23: Who can read memory records across every actor."""

    _MEMORY_ARN = "arn:aws:bedrock-agentcore:us-east-1:123456789012:memory/mem-1"

    @staticmethod
    def _cache(
        actions,
        condition=None,
        resource="*",
        principal="agent-role",
        effect="Allow",
    ):
        statement = {"Effect": effect, "Action": actions, "Resource": resource}
        if condition:
            statement["Condition"] = condition
        return {
            "role_permissions": {
                principal: {
                    "attached_policies": [
                        {"name": "p", "document": {"Statement": [statement]}}
                    ],
                    "inline_policies": [],
                }
            },
            "user_permissions": {},
        }

    def test_unscoped_record_read_fails(self):
        findings = agentcore_app.check_agentcore_memory_record_access_scope(
            self._cache(["bedrock-agentcore:RetrieveMemoryRecords"])
        )
        assert [f["Status"] for f in findings] == ["Failed"]
        assert findings[0]["Check_ID"] == "AC-23"
        assert findings[0]["Severity"] == "High"
        assert "role agent-role" in findings[0]["Finding_Details"]
        for finding in findings:
            assert_finding_schema(finding)

    def test_namespace_condition_passes(self):
        findings = agentcore_app.check_agentcore_memory_record_access_scope(
            self._cache(
                ["bedrock-agentcore:RetrieveMemoryRecords"],
                condition={
                    "StringLike": {
                        "bedrock-agentcore:namespace": (
                            "/actors/${aws:PrincipalTag/actorId}/*"
                        )
                    }
                },
            )
        )
        assert [f["Status"] for f in findings] == ["Passed"]
        assert "role agent-role" in findings[0]["Finding_Details"]

    def test_actor_condition_on_event_read_passes(self):
        findings = agentcore_app.check_agentcore_memory_record_access_scope(
            self._cache(
                ["bedrock-agentcore:ListEvents", "bedrock-agentcore:GetEvent"],
                condition={
                    "StringEquals": {
                        "bedrock-agentcore:actorId": "${aws:PrincipalTag/actorId}"
                    }
                },
            )
        )
        assert [f["Status"] for f in findings] == ["Passed"]

    def test_devguide_namespace_variable_key_counts_as_scope(self):
        # namespaceVariable/<key> is published in the devguide tenant-isolation
        # example but is absent from the IAM service authorization reference. The
        # verdict is the same either way: the key scopes the read if it exists,
        # and the condition can never match if it does not.
        findings = agentcore_app.check_agentcore_memory_record_access_scope(
            self._cache(
                ["bedrock-agentcore:ListMemoryRecords"],
                condition={
                    "StringEquals": {
                        "bedrock-agentcore:namespaceVariable/tenantId": (
                            "${aws:PrincipalTag/tenantId}"
                        )
                    }
                },
            )
        )
        assert [f["Status"] for f in findings] == ["Passed"]

    def test_memory_arn_resource_without_a_condition_still_fails(self):
        # The only resource type these actions accept is the memory itself, so
        # naming the ARN still reads every actor's records inside it.
        findings = agentcore_app.check_agentcore_memory_record_access_scope(
            self._cache(
                ["bedrock-agentcore:RetrieveMemoryRecords"], resource=self._MEMORY_ARN
            )
        )
        assert [f["Status"] for f in findings] == ["Failed"]

    def test_agentcore_namespace_wildcard_is_detected(self):
        findings = agentcore_app.check_agentcore_memory_record_access_scope(
            self._cache(["bedrock-agentcore:*"])
        )
        assert [f["Status"] for f in findings] == ["Failed"]

    def test_bare_wildcard_action_is_detected(self):
        # Stricter than before: this asserted Passed with "No cached IAM role
        # or user", reading an Action "*" grant as no memory read at all.
        findings = agentcore_app.check_agentcore_memory_record_access_scope(
            self._cache(["*"])
        )
        assert [f["Status"] for f in findings] == ["Failed"]
        assert "role agent-role" in findings[0]["Finding_Details"]

    def test_actions_iam_cannot_scope_are_not_assessed(self):
        # IAM publishes no namespace, actor, session or strategy condition key
        # for GetMemoryRecord or ListActors, so a Failed verdict on them would
        # demand a policy that cannot be written.
        findings = agentcore_app.check_agentcore_memory_record_access_scope(
            self._cache(
                [
                    "bedrock-agentcore:GetMemoryRecord",
                    "bedrock-agentcore:ListActors",
                ]
            )
        )
        assert [f["Status"] for f in findings] == ["Passed"]
        assert "No cached IAM role or user" in findings[0]["Finding_Details"]

    def test_deny_statement_is_ignored(self):
        findings = agentcore_app.check_agentcore_memory_record_access_scope(
            self._cache(["bedrock-agentcore:RetrieveMemoryRecords"], effect="Deny")
        )
        assert [f["Status"] for f in findings] == ["Passed"]
        assert "No cached IAM role or user" in findings[0]["Finding_Details"]

    def test_another_service_read_is_ignored(self):
        findings = agentcore_app.check_agentcore_memory_record_access_scope(
            self._cache(["qbusiness:ListEvents"])
        )
        assert [f["Status"] for f in findings] == ["Passed"]
        assert "No cached IAM role or user" in findings[0]["Finding_Details"]

    def test_a_scoped_statement_does_not_excuse_an_unscoped_one(self):
        cache = self._cache(
            ["bedrock-agentcore:ListMemoryRecords"],
            condition={"StringEquals": {"bedrock-agentcore:strategyId": "strat-1"}},
        )
        cache["role_permissions"]["agent-role"]["inline_policies"] = [
            {
                "name": "wide",
                "document": {
                    "Statement": [
                        {
                            "Effect": "Allow",
                            "Action": "bedrock-agentcore:RetrieveMemoryRecords",
                            "Resource": "*",
                        }
                    ]
                },
            }
        ]

        findings = agentcore_app.check_agentcore_memory_record_access_scope(cache)

        assert [f["Status"] for f in findings] == ["Failed"]

    def test_users_are_evaluated_alongside_roles(self):
        cache = self._cache(["bedrock-agentcore:RetrieveMemoryRecords"])
        cache["user_permissions"] = cache["role_permissions"]
        cache["role_permissions"] = {}

        findings = agentcore_app.check_agentcore_memory_record_access_scope(cache)

        assert [f["Status"] for f in findings] == ["Failed"]
        assert "user agent-role" in findings[0]["Finding_Details"]

    def test_scoped_and_unscoped_principals_are_reported_separately(self):
        cache = self._cache(["bedrock-agentcore:RetrieveMemoryRecords"])
        cache["role_permissions"]["scoped-role"] = {
            "attached_policies": [
                {
                    "name": "p",
                    "document": {
                        "Statement": [
                            {
                                "Effect": "Allow",
                                "Action": "bedrock-agentcore:RetrieveMemoryRecords",
                                "Resource": "*",
                                "Condition": {
                                    "StringLike": {
                                        "bedrock-agentcore:namespace": "/actors/a-1/*"
                                    }
                                },
                            }
                        ]
                    },
                }
            ],
            "inline_policies": [],
        }

        findings = agentcore_app.check_agentcore_memory_record_access_scope(cache)

        assert {finding["Status"] for finding in findings} == {"Failed", "Passed"}

    @pytest.mark.parametrize(
        "namespace,status",
        [
            ("/users/*", "Failed"),
            ("/actors/*", "Failed"),
            ("/strategies/s-1/actors/*", "Failed"),
            ("/sessions/*", "Failed"),
            ("/*", "Failed"),
            ("/actors/a-*/*", "Failed"),
            ("/actors/alice*", "Failed"),
            ("/actors/a-?", "Failed"),
            ("/actors/a-1/*", "Passed"),
            ("/actors/a-1/sessions/*", "Passed"),
            ("/users/alice/*", "Passed"),
            ("/actors/a-1/sessions/s-1", "Passed"),
        ],
    )
    def test_a_stringlike_namespace_that_spans_callers_is_unscoped(
        self, namespace, status
    ):
        # '/users/*' was read as a fixed partition and passed, though it
        # matches every user's records.
        findings = agentcore_app.check_agentcore_memory_record_access_scope(
            self._cache(
                ["bedrock-agentcore:RetrieveMemoryRecords"],
                condition={"StringLike": {"bedrock-agentcore:namespace": namespace}},
            )
        )
        assert [f["Status"] for f in findings] == [status]

    def test_a_users_wildcard_role_fails_beside_a_scoped_role(self):
        cache = self._cache(
            ["bedrock-agentcore:RetrieveMemoryRecords"],
            condition={"StringLike": {"bedrock-agentcore:namespace": "/users/*"}},
            principal="wide-role",
        )
        cache["role_permissions"].update(
            self._cache(
                ["bedrock-agentcore:RetrieveMemoryRecords"],
                condition={
                    "StringLike": {"bedrock-agentcore:namespace": "/actors/a-1/*"}
                },
                principal="scoped-role",
            )["role_permissions"]
        )

        findings = agentcore_app.check_agentcore_memory_record_access_scope(cache)

        failed = [f for f in findings if f["Status"] == "Failed"]
        assert len(failed) == 1
        assert "role wide-role" in failed[0]["Finding_Details"]
        assert "scoped-role" not in failed[0]["Finding_Details"]

    def test_findings_are_tagged_global(self):
        findings = agentcore_app.check_agentcore_memory_record_access_scope(
            self._cache(["bedrock-agentcore:RetrieveMemoryRecords"])
        )
        assert all(
            finding["Region"] == agentcore_app.GLOBAL_REGION_LABEL
            for finding in findings
        )

    def test_empty_cache_is_na(self):
        findings = agentcore_app.check_agentcore_memory_record_access_scope(
            {"role_permissions": {}, "user_permissions": {}}
        )
        assert findings[0]["Status"] == "N/A"

    def test_unparseable_policy_does_not_hide_a_sibling_grant(self):
        cache = self._cache(["bedrock-agentcore:RetrieveMemoryRecords"])
        cache["role_permissions"]["agent-role"]["inline_policies"] = [
            {"name": "broken", "document": "{not json"}
        ]

        findings = agentcore_app.check_agentcore_memory_record_access_scope(cache)

        # Stricter than before: this asserted ["Failed"] alone, so the unread
        # policy went unreported.
        assert [f["Status"] for f in findings] == ["N/A", "Failed"]
        assert "role agent-role (policy broken)" in findings[0]["Finding_Details"]

    def test_unusable_cache_is_reported_incomplete(self):
        findings = agentcore_app.check_agentcore_memory_record_access_scope(None)

        assert [f["Status"] for f in findings] == ["N/A"]
        assert findings[0]["Finding"].endswith("Incomplete")

    def test_read_actions_name_real_api_operations(self):
        # A typo in this tuple would silently narrow the check to nothing.
        model = agentcore_app.boto3.client(
            "bedrock-agentcore",
            region_name="us-east-1",
            aws_access_key_id="testing",
            aws_secret_access_key="testing",  # pragma: allowlist secret - synthetic test credential
        ).meta.service_model
        operations = {name.lower() for name in model.operation_names}
        assert set(agentcore_app.MEMORY_RECORD_READ_ACTIONS) <= operations
        # The two deliberately excluded reads exist as well, so their absence
        # from the tuple is a scoping decision and not a misspelling.
        assert {"getmemoryrecord", "listactors"} <= operations
        assert {"getmemoryrecord", "listactors"}.isdisjoint(
            agentcore_app.MEMORY_RECORD_READ_ACTIONS
        )


