        assert mock_orgs.list_policies.call_count == 2
        assert mock_orgs.list_policies.call_args_list[1].kwargs["NextToken"] == "page-2"
        assert findings[0]["Status"] == "Passed"
        assert "DenySigV4Runtime" in findings[0]["Finding_Details"]

