def _model_policy(resource, action=None):
    return {
        "name": "EvaluationPolicy",
        "document": {
            "Statement": {
                "Effect": "Allow",
                "Action": action
                or ["bedrock:InvokeModel", "bedrock:InvokeModelWithResponseStream"],
                "Resource": resource,
            }
        },
    }


