        assert "missing 4 of the five" in findings[0]["Finding_Details"]
        for missing in (
            "a rule that blocks",
            "SQL injection inspection",
            "cross-site scripting inspection",
            "a rate-based rule",
        ):
            assert missing in findings[0]["Finding_Details"]

