def _ecr_repo(name):
    return {"repositoryName": name}


def _scanning(scan_type, *rules):
    return {
        "scanningConfiguration": {
            "scanType": scan_type,
            "rules": [
                {
                    "scanFrequency": frequency,
                    "repositoryFilters": [
                        {"filter": pattern, "filterType": "WILDCARD"}
                        for pattern in patterns
                    ],
                }
                for frequency, patterns in rules
            ],
        }
    }


